class Solution {
public:
    bool isBoomerang(vector<vector<int>>& points) {
        long long dx1 = points[1][0] - points[0][0], dy1 = points[1][1] - points[0][1];
        long long dx2 = points[2][0] - points[0][0], dy2 = points[2][1] - points[0][1];
        return dx1 * dy2 - dy1 * dx2 != 0;
    }
};

